('860000004', 'demo', '沉默用户召回实验', '筛选 30 天未活跃用户，设计三组差异化召回内容，并跟踪回访与关键动作完成率。', '用户运营', '2026-07-11 10:30', '2026-07-24 18:00', NULL, '2026-07', 10, 4.5, 260, '苏晚晴', '程木', '孟溪', '等待素材', '挂起', 38, '', '[{"id":"demo-ops-3","date":"2026-07-12","start":"10:30","end":"15:00","note":"完成用户分群与第一版召回文案"}]', '[{"id":"demo-wait-1","date":"2026-07-18","start":"16:20","end":"16:20","note":"等待法务确认优惠券表达","reason":"等待补充资料"}]', 1, '2026-07-11 10:12', '2026-07-18 16:20'),
