('860000007', 'demo', '企业知识库 RAG 评测框架', '建立覆盖检索、引用、拒答与冲突信息处理的评测集，支持模型版本之间的稳定对比。', 'AI 研究员', '2026-07-05 10:00', '2026-07-29 18:00', NULL, '2026-07', 28, 18, 260, '季衡', '夏沐', '宋启', '基线评测', '进行中', 68, '', '[{"id":"demo-ai-1","date":"2026-07-07","start":"10:00","end":"18:00","note":"定义评测维度并整理 60 条样本"},{"id":"demo-ai-2","date":"2026-07-21","start":"09:30","end":"19:30","note":"完成首轮基线运行与错误归因"}]', '[]', 1, '2026-07-05 09:44', '2026-07-21 19:30'),
('860000008', 'demo', '提示词鲁棒性对照实验', '验证角色提示、格式约束和工具失败情况下的输出稳定性，形成上线前检查清单。', 'AI 研究员', '2026-06-10 09:30', '2026-06-24 18:00', '2026-06-24 17:10', '2026-06', 20, 16.5, 260, '季衡', '乔安', '宋启', '实验归档', '已验收', 100, '评测记录完整，三个高风险模式均已加入回归集。', '[{"id":"demo-ai-3","date":"2026-06-11","start":"09:30","end":"17:30","note":"搭建变量矩阵和自动评分脚本"},{"id":"demo-ai-4","date":"2026-06-23","start":"09:30","end":"18:00","note":"完成对照实验与风险清单","isAcceptanceProgress":true}]', '[]', 1, '2026-06-10 09:20', '2026-06-24 17:10'),
('860000009', 'demo', '研发岗位招聘漏斗复盘', '复盘前端、后端与数据岗位从简历到 Offer 的转化，定位筛选标准和面试协作问题。', 'HR / 人力资源', '2026-06-20 09:00', '2026-06-30 18:00', '2026-06-30 16:30', '2026-06', 12, 10, 260, '白露', '贺青', '姚宁', '复盘完成', '已验收', 100, '招聘团队已采用统一评分卡和候选人沟通节点。', '[{"id":"demo-hr-1","date":"2026-06-22","start":"09:00","end":"15:00","note":"完成漏斗统计和岗位差异分析"},{"id":"demo-hr-2","date":"2026-06-29","start":"13:00","end":"17:00","note":"组织复盘会并确认改进动作","isAcceptanceProgress":true}]', '[]', 1, '2026-06-20 08:40', '2026-06-30 16:30'),
